function updateNavigation(){const records=state.library.items.filter(YingjiMarks.marked),visible=YingjiMarks.visibleIds(state.library.items);for(const[id]of routes){const selected=state.tab==='library'?state.collectionMode===id:state.tab===id;document.querySelector('[data-route="'+id+'"]').classList.toggle('active',selected);const count=id==='all'?records.length:id==='watched'?records.filter(i=>i.status==='watched').length:id==='favorites'?records.filter(i=>i.favorite).length:id==='personal'?records.filter(i=>i.manual===true).length:id==='media'?state.library.items.filter(i=>['image','video'].includes(i.type)&&visible.has(i.id)).length:id==='sources'?state.library.sources.length:0;const n=document.querySelector('[data-route-count="'+id+'"]');n.textContent=count?String(count):''}$('.brand-caption').textContent=routes.find(r=>r[0]===(state.tab==='library'?state.collectionMode:state.tab))?.[2]||'作品资料库'}
