filtered=function(){const visible=YingjiMarks.visibleIds(state.library.items);let rows=originalFilter().filter(i=>visible.has(i.id));if(state.collectionMode==='all')rows=rows.filter(i=>i.type==='record');if(state.collectionMode==='watched')rows=rows.filter(i=>YingjiMarks.matches(i,state.markedView||'all'));if(state.collectionMode==='favorites')rows=rows.filter(i=>i.type==='record'&&i.favorite);if(state.collectionMode==='personal')rows=rows.filter(i=>i.type==='record'&&i.manual===true);if(state.collectionMode==='media')rows=rows.filter(i=>i.type!=='record'&&(!i.coverOnly||state.library.items.some(w=>w.materialIds?.includes(i.id))));return rows};
