let thumbObserver;queueThumbnails=function(){thumbObserver?.disconnect();for(let n=thumbnailQueue.length-1;n>=0;n--)if(!thumbnailQueue[n].node.isConnected||(!$('#overlay').hidden&&!$('#sheet').contains(thumbnailQueue[n].node)))thumbnailQueue.splice(n,1);thumbObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){thumbObserver.unobserve(e.target);const id=e.target.dataset.thumbnail;if(thumbnailCache.has(id)){setThumbnail(e.target,thumbnailCache.get(id));continue}const item=state.library.items.find(i=>i.id===id)||catalogClient.byId.get(id);if(!item||(!['image','video'].includes(item.type)&&!item.coverUrl))continue;thumbnailQueue.push({id,node:e.target});pumpThumbnails()}},{root:$('#overlay').hidden?mainElement:$('#sheet'),rootMargin:'180px'});document.querySelectorAll('[data-thumbnail]').forEach(n=>thumbObserver.observe(n))};
function catalogRow(work){const w=savedWork(work);return`<article class="catalog-row" data-catalog-open="${esc(w.id)}" tabindex="0" role="button" aria-label="打开 ${esc(w.title)}"><div class="catalog-poster">${recordCover(w)}</div><div><div class="catalog-row-title"><h3>${esc(w.title)}</h3>${w.rank?`<span class="rank-label">Rank ${w.rank}</span>`:''}</div><p class="catalog-original">${esc(w.original||w.description?.slice(0,100)||'')}</p><div class="catalog-meta"><span>${esc(w.date||'日期待补充')}</span><span class="type-badge">${esc(w.format||w.category)}</span>${w.eps?`<span>${w.eps} 话</span>`:''}${w.sourceScore?`<span class="score">★ ${Number(w.sourceScore).toFixed(1)}</span>`:''}${w.sourceVotes?`<span>${w.sourceVotes.toLocaleString()} 人评分</span>`:''}${w.status==='watched'?'<span class="completed-label">看过</span>':''}</div></div><div class="catalog-row-actions">${quickActions(w,'catalog')}</div></article>`}
