function renderCatalog(){const years=Array.from({length:new Date().getFullYear()-1977+1},(_,i)=>String(new Date().getFullYear()-i));$('#main').innerHTML=heading('DISCOVER YOUR NEXT STORY','总有一个故事，值得相遇。','按年份探索动画、剧场版与影视作品，留下你的观看足迹。')+`<div class="page-title-actions" style="position:absolute;right:30px;top:28px"><button class="button secondary" data-catalog-refresh>${svg('refresh')}更新近期</button></div><div class="catalog-toolbar"><div class="search">${svg('search')}<input id="catalogSearch" value="${esc(catalogClient.query)}" placeholder="搜索中文名、日文名或英文名…" aria-label="搜索在线作品"></div>${select('catalogProvider',[['bangumi','Bangumi'],['tmdb','TMDB 影视库']],catalogClient.provider)}${select('catalogKind',[['anime','动画番剧'],['anime-film','动画电影'],['movie','真人电影'],['tv','电视剧'],['game','游戏 · Bangumi'],['book','书籍 · Bangumi'],['music','音乐 · Bangumi']],catalogClient.kind)}${select('catalogYear',[['all','全部年份'],...years.map(y=>[y,y+' 年'])],catalogClient.year)}${select('catalogSort',[['rank','排名'],['trends','热度'],['collects','收藏'],['date','日期'],['title','名称']],catalogClient.sort)}</div><div class="catalog-note">${svg('globe')}<span>${catalogClient.provider==='bangumi'?'Bangumi 源站作品资料 · 部分浏览方式需要登录 · 封面和已访问页面会缓存到本机':'TMDB 提供更广的影视资料 · 需在设置中填写你自己的免费 API 密钥'}</span></div><div class="catalog-summary"><span id="catalogSummary">${catalogClient.loading?'正在读取作品资料…':'作品列表'}</span><div class="view-switch"><button data-catalog-view="list" aria-label="作品列表视图" class="${catalogClient.view==='list'?'active':''}">${svg('list')}</button><button data-catalog-view="grid" aria-label="作品封面墙" class="${catalogClient.view==='grid'?'active':''}">${svg('grid')}</button></div></div><div id="catalogResults"></div><p class="file-count-note">覆盖所选数据源已收录的作品，不保证全球零遗漏。观看、收藏和评分记录保存在你的本机资料库，不修改源站账号。</p>`;let searchTimer;$('#catalogSearch').oninput=e=>{clearTimeout(searchTimer);const value=e.target.value;catalogClient.query=value;searchTimer=setTimeout(()=>{catalogClient.query=value;catalogClient.page=1;loadCatalog()},300)};for(const[id,key]of [['catalogProvider','provider'],['catalogKind','kind'],['catalogYear','year'],['catalogSort','sort']])$('#'+id).onchange=e=>{catalogClient[key]=e.target.value;catalogClient.page=1;loadCatalog()};const headingRow=$('#main .heading-row'),titleActions=$('#main [data-catalog-refresh]')?.parentElement;if(headingRow&&titleActions){titleActions.removeAttribute('style');headingRow.append(titleActions);}if(catalogClient.result&&!catalogClient.loading)renderCatalogResults();else loadCatalog()}
function renderCatalogResults(){if(!$('#catalogResults'))return;document.querySelectorAll('[data-catalog-view]').forEach(b=>b.classList.toggle('active',b.dataset.catalogView===catalogClient.view));if(catalogClient.loading){$('#catalogResults').innerHTML='<div class="catalog-loading">'+Array.from({length:4},()=>'<div class="catalog-skeleton"></div>').join('')+'</div>';return}if(catalogClient.error){$('#catalogSummary').textContent='暂时无法载入';$('#catalogResults').innerHTML=`<div class="catalog-empty"><b>作品资料暂未载入</b>${esc(catalogClient.error)}<br><button class="button secondary" data-catalog-retry>重新读取</button><button class="button secondary" data-route="settings" style="margin-left:8px">前往设置</button></div>`;return}const r=catalogClient.result;$('#catalogSummary').innerHTML=`<b>${catalogClient.items.length} 部作品</b> · 第 ${catalogClient.page} 页 <span class="source-pill">${r?.offline?'离线缓存':r?.cached?'本地缓存':'在线资料'}</span>`;$('#catalogResults').innerHTML=(catalogClient.items.length?`<div class="${catalogClient.view==='grid'?'catalog-grid':'catalog-list'}">${catalogClient.items.map(catalogClient.view==='grid'?catalogCard:catalogRow).join('')}</div>`:'<div class="catalog-empty"><b>这个条件下还没有找到作品</b>试试更换年份、作品类型或关键词。</div>')+`<div class="catalog-pagination"><button class="button secondary" data-catalog-page="prev" ${catalogClient.page<=1?'disabled':''}>上一页</button><span>第 ${catalogClient.page} 页</span><button class="button secondary" data-catalog-page="next" ${!catalogClient.hasMore?'disabled':''}>下一页</button></div>`;queueThumbnails()}
async function loadCatalog(refresh=false){if(catalogClient.forceRefresh){refresh=true;catalogClient.forceRefresh=false}const requestId=++catalogClient.requestId;catalogClient.loading=true;catalogClient.error='';renderCatalogResults();if($('#catalogSummary'))$('#catalogSummary').textContent='正在读取作品资料…';try{const result=await invoke('catalogBrowse',{provider:catalogClient.provider,kind:catalogClient.kind,year:catalogClient.year,sort:catalogClient.sort,query:catalogClient.query,page:catalogClient.page,refresh});if(requestId!==catalogClient.requestId)return;catalogClient.items=result.items;catalogClient.total=result.total;catalogClient.hasMore=result.hasMore;catalogClient.result=result;for(const item of result.items)catalogClient.byId.set(item.id,item);setTaskStatus(result.offline?'网络不可用，正在显示本地缓存':'作品资料已载入 · '+result.items.length+' 部')}catch(e){if(requestId!==catalogClient.requestId)return;catalogClient.error=e.message;setTaskStatus('在线作品库暂未载入')}finally{if(requestId===catalogClient.requestId){catalogClient.loading=false;if(state.tab==='catalog')renderCatalogResults()}}}
function setTaskStatus(message,busy=false){$('#appTaskStatus').textContent=message;$('#taskIndicator').className=busy?'status-spinner':'status-indicator'}
