function confirmRemoveSource(source){sourcePendingRemoval=source;showSheet(`<div class="detail-kicker">REMOVE LIBRARY SOURCE</div><h2 class="detail-title">移除这个文件来源？</h2><div class="page-note">${esc(source)}</div><p class="summary">只从映迹取消此文件夹的连接，不删除电脑里的原文件。看过、已收藏、手动编辑的条目和它们关联的素材会保留在个人资料库。</p><div class="button-group"><button class="button secondary" data-action="close">保留来源</button><button class="button danger" data-confirm-remove-source>移除来源</button></div>`)}
editEntry=async function(item){if(item?.provider&&!state.library.items.some(i=>i.id===item.id)){state.library=await invoke('watch',{id:item.id,status:'pending'});}originalEdit(item);const old=$('#entryCategory');if(!old)return;const selected=old.value||item?.category||'电影';const holder=document.createElement('div');holder.className='category-control';const categorySelect=document.createElement('select');categorySelect.id='entryCategory';categorySelect.name='category';categorySelect.className='form-input';const values=[...new Set([...YingjiCategories.DEFAULTS,...(state.library.categories||[]),...state.library.items.map(i=>i.category).filter(Boolean),selected])];categorySelect.innerHTML=options(values.map(v=>[v,v]),selected);const add=document.createElement('button');add.type='button';add.className='button secondary';add.dataset.newCategory='true';add.textContent='新建类目';old.replaceWith(holder);holder.append(categorySelect,add);const inline=document.createElement('div');inline.className='new-category-row';inline.hidden=true;inline.innerHTML='<input id="newCategoryName" class="form-input" maxlength="80" placeholder="输入新类目名称" aria-label="新类目名称"><button type="button" class="button" data-save-category>添加并选中</button>';holder.after(inline)};
renderSettings=function(){originalSettings();if(state.tab!=='settings')return;const panels=[...$('#main').querySelectorAll(':scope>.panel')];const columns=document.createElement('div');columns.className='settings-columns';const left=document.createElement('div'),right=document.createElement('div');panels.forEach((p,i)=>(i%2?right:left).append(p));const tmdb=document.createElement('div');tmdb.className='panel';tmdb.innerHTML='<h3>影视数据源 · TMDB</h3><p>Bangumi 可以直接浏览动画、剧场版和已收录的影视作品。TMDB 提供更广的真人电影、电视剧资料，需要你自己的免费 API 密钥或 API Read Access Token。</p><div class="tmdb-input"><input type="password" id="tmdbSecret" class="form-input" autocomplete="off" placeholder="粘贴 TMDB API 密钥或读取令牌" aria-label="TMDB API 密钥"><button class="button secondary" data-save-tmdb>保存</button></div><p class="hint">密钥使用 Windows 凭据保护加密保存在本机。已保存的密钥不会在界面中回显。申请入口：themoviedb.org/settings/api</p>';right.prepend(tmdb);columns.append(left,right);$('#main').append(columns);const about=[...$('#main').querySelectorAll('p')].find(p=>p.textContent.includes('Windows 桌面版 0.1.0'));if(about)about.textContent='映迹 · Windows 桌面版 0.4.1\n在线作品库 / 本地素材 / 观看收藏 / 单集评分\n工作线程扫描、增量索引、封面缓存与原文件保护。'};
openItem=async function(id){if(/^(bgm-|tmdb-)/.test(id))return openCatalogWork(id);return originalOpen(id)};
async function openCatalogWork(id){const known=state.library.items.find(i=>i.id===id)||catalogClient.byId.get(id);current=known||{id};showSheet(`<div class="detail-kicker">WORK DETAILS</div><h2 class="detail-title">${esc(known?.title||'正在读取作品')}</h2><div class="loading-bar"><i></i></div><p class="loading-text">正在载入作品详情与单集资料…</p>`,'catalog-detail');try{const data=catalogClient.details.get(id)||await invoke('catalogDetail',id);if(current?.id!==id)return;catalogClient.details.set(id,data);catalogClient.byId.set(id,data.work);catalogDetailState={...data,id};current=savedWork(data.work);renderCatalogDetail()}catch(e){if(current?.id!==id||$('#overlay').hidden)return;if($('#sheet'))$('#sheet').innerHTML=`<button class="sheet-close" aria-label="关闭详情" data-action="close">×</button><div class="error-note">${esc(e.message)}</div>${known?`<h2 class="detail-title">${esc(known.title)}</h2><div class="button-group">${quickActions(known,'catalog')}</div>`:''}`}}
function episodeValue(work,ep){const stored=work.episodeStates?.[ep.id]||{};return{state:work.allWatched?'watched':'pending',score:0,review:'',...stored}}
function renderCatalogDetail(){if(!catalogDetailState)return;const work=savedWork(catalogDetailState.work);current=work;const episodes=catalogDetailState.episodes||[];$('#sheet').className='sheet catalog-detail';$('#sheet').innerHTML=`<button class="sheet-close" aria-label="关闭详情" data-action="close">×</button><div class="detail-kicker">${esc(work.source||'BANGUMI')} / WORK DETAILS</div><h2 class="detail-title">${esc(work.title)}</h2><p class="detail-original">${esc(work.original||'')}</p><div class="catalog-detail-layout"><div><div class="detail-cover">${recordCover(work)}</div><div class="detail-side-info">数据源：${esc(work.source)}<br>${work.rank?'源站排名：'+work.rank+'<br>':''}${work.sourceScore?'源站评分：'+Number(work.sourceScore).toFixed(1)+' / 10<br>':''}出品：${esc(work.date||'日期待补充')}<br>${work.eps?'全 '+work.eps+' 话':'集数以源站更新为准'}</div></div><div class="detail-main-info"><div class="detail-watch-actions">${quickActions(work,'detail')}<button class="action-pill ${work.status==='watching'?'done':''}" data-detail-action="watching" data-id="${work.id}">${svg('play')}在看</button><button class="action-pill" data-detail-action="pending" data-id="${work.id}">待看</button></div><div class="detail-facts"><div><label>类目</label><p>${esc(work.category)}</p></div><div><label>形式</label><p>${esc(work.format||'—')}</p></div><div><label>作者 / 主创</label><p>${esc(work.author||'源站暂未提供')}</p></div></div><div class="detail-description">${esc(work.description||'这个作品暂时没有简介。')}</div><div class="detail-review-row"><label for="workPersonalScore">我的评分</label><select id="workPersonalScore" aria-label="整部作品评分">${options([['0','暂不评分'],...Array.from({length:10},(_,i)=>[String(i+1),(i+1)+' 分'])],String(work.personalScore||0))}</select><button class="button small secondary" data-save-work-review>保存评分与评论</button><button class="ghost-link" data-action="edit-current">编辑资料</button></div><textarea id="workReview" class="form-input detail-review" aria-label="整部作品评论" placeholder="写下对整部作品的感受…">${esc(work.review||'')}</textarea><p class="detail-state-note">首次收藏会默认将整部作品和已知集数标记为看过；单集仍可自行调整。</p>${episodes.length?`<div class="episode-header"><h3>单集记录 <span>已载入 ${episodes.length} / ${catalogDetailState.episodeTotal||episodes.length} 话</span></h3><span>角标轮换：待看 / 看过 / 重点</span></div><div class="episode-grid">${episodes.map(ep=>{const value=episodeValue(work,ep);return`<div class="episode-card"><button class="ep-cycle ${value.state}" data-episode-cycle="${esc(ep.id)}" aria-label="第 ${ep.number} 集 ${value.state==='watched'?'看过':value.state==='important'?'重点':'待看'}，点击切换">${value.state==='watched'?'✓':value.state==='important'?'★':'○'}</button><button data-episode-edit="${esc(ep.id)}"><span class="ep-heading">第 ${ep.number} 话</span><span class="ep-name">${esc(ep.title||'单集标题待补充')}</span>${value.score?`<span class="ep-score">我的评分 ${value.score} / 10</span>`:''}${value.review?'<span class="ep-score">已有单集评论</span>':''}</button></div>`}).join('')}</div><div id="episodeEditor"></div>${catalogDetailState.episodeHasMore?'<button class="more-episodes" data-more-episodes>载入更多集数</button>':''}`:work.eps>1?'<p class="hint">此数据源暂未提供可读取的单集列表。整部作品的观看、收藏与评分仍可记录。</p>':''}</div></div>`;queueThumbnails()}
function renderEpisodeEditor(id){const ep=catalogDetailState?.episodes.find(e=>e.id===id);if(!ep)return;episodeEditing=id;const value=episodeValue(savedWork(catalogDetailState.work),ep);$('#episodeEditor').innerHTML=`<div class="episode-editor"><label>第 ${ep.number} 话 · ${esc(ep.title)}</label><div class="detail-review-row"><label>单集评分</label><select id="episodeScore">${options([['0','暂不评分'],...Array.from({length:10},(_,i)=>[String(i+1),(i+1)+' 分'])],String(value.score||0))}</select><button class="button small secondary" data-save-episode>保存单集记录</button></div><textarea id="episodeReview" class="form-input" aria-label="单集评论" placeholder="这集有什么想记住的？">${esc(value.review||'')}</textarea></div>`;$('#episodeEditor').scrollIntoView({block:'nearest',behavior:'smooth'})}
async function persistWatch(id,patch,showFeedback=true){const button=document.activeElement;const busyButton=button?.tagName==='BUTTON'?button:null;if(busyButton)busyButton.disabled=true;const scroll=$('#sheet').scrollTop;try{const result=await invoke('watch',{id,...patch});state.library=result;updateNavigation();if(catalogDetailState?.id===id&&!$('#overlay').hidden){renderCatalogDetail();$('#sheet').scrollTop=scroll}else if(state.tab==='catalog')renderCatalogResults();else if(state.tab==='library')renderResults();if(showFeedback)toast('观看记录已保存在本机');return result}catch(e){toast(e.message)}finally{if(busyButton?.isConnected)busyButton.disabled=false}}
async function performWatch(id,action){const known=state.library.items.find(i=>i.id===id)||catalogClient.byId.get(id)||catalogDetailState?.work;if(!known)return;const patch=action==='favorite'?{favorite:!known.favorite}:action==='watched'?{status:known.status==='watched'?'pending':'watched'}:{status:action};if(catalogDetailState?.id===id&&$('#workReview')){patch.review=$('#workReview').value;patch.personalScore=Number($('#workPersonalScore').value)}await persistWatch(id,patch)}
document.addEventListener('click',async e=>{const action=e.target.closest('[data-entry-action],[data-catalog-action],[data-detail-action]');if(action){e.preventDefault();e.stopImmediatePropagation();await performWatch(action.dataset.id,action.dataset.entryAction||action.dataset.catalogAction||action.dataset.detailAction);return}const windowButton=e.target.closest('[data-window-action]');if(windowButton){e.stopImmediatePropagation();await invoke('windowControl',windowButton.dataset.windowAction);return}const route=e.target.closest('[data-route]');if(route){e.stopImmediatePropagation();navigate(route.dataset.route);return}const open=e.target.closest('[data-catalog-open]');if(open){e.stopImmediatePropagation();await openCatalogWork(open.dataset.catalogOpen);return}const cv=e.target.closest('[data-catalog-view]');if(cv){catalogClient.view=cv.dataset.catalogView;localStorage.setItem('yingji-catalog-wall-v041',catalogClient.view);renderCatalogResults();return}if(e.target.closest('[data-catalog-refresh]')){catalogClient.quarter='all';catalogClient.region='all';catalogClient.year=String(new Date().getFullYear());catalogClient.sort='date';catalogClient.page=1;catalogClient.query='';catalogClient.result=null;catalogClient.forceRefresh=true;renderCatalog();return}if(e.target.closest('[data-catalog-retry]')){await loadCatalog(true);return}const pg=e.target.closest('[data-catalog-page]');if(pg){catalogClient.page+=pg.dataset.catalogPage==='next'?1:-1;await loadCatalog();mainElement.scrollTop=0;return}const rm=e.target.closest('[data-remove-source]');if(rm){confirmRemoveSource(rm.dataset.removeSource);return}if(e.target.closest('[data-confirm-remove-source]')){try{state.library=await invoke('removeSource',sourcePendingRemoval);closeSheet();render();toast('文件来源已移除，电脑上的原文件保留')}catch(err){toast(err.message)}return}if(e.target.closest('[data-new-category]')){const row=$('.new-category-row');row.hidden=!row.hidden;if(!row.hidden)$('#newCategoryName').focus();return}if(e.target.closest('[data-save-category]')){const value=$('#newCategoryName').value.trim();try{state.library=await invoke('addCategory',value);const select=$('#entryCategory');select.innerHTML=options(state.library.categories.map(c=>[c,c]),value);select.value=value;$('.new-category-row').hidden=true;toast('新类目已保存，下次添加条目时也可直接选择')}catch(err){toast(err.message)}return}if(e.target.closest('[data-save-tmdb]')){try{const value=$('#tmdbSecret').value;await invoke('setTmdbToken',value);$('#tmdbSecret').value='';toast(value.trim()?'TMDB 密钥已加密保存':'TMDB 密钥已清除')}catch(err){toast(err.message)}return}if(e.target.closest('[data-save-work-review]')){await persistWatch(current.id,{personalScore:Number($('#workPersonalScore').value),review:$('#workReview').value});return}const cycle=e.target.closest('[data-episode-cycle]');if(cycle){const id=cycle.dataset.episodeCycle,ep=catalogDetailState.episodes.find(e=>e.id===id),value=episodeValue(savedWork(catalogDetailState.work),ep),states=['pending','watched','important'];await persistWatch(current.id,{episode:{id,state:states[(states.indexOf(value.state)+1)%3]}},false);return}const epEdit=e.target.closest('[data-episode-edit]');if(epEdit){renderEpisodeEditor(epEdit.dataset.episodeEdit);return}if(e.target.closest('[data-save-episode]')){await persistWatch(current.id,{episode:{id:episodeEditing,score:Number($('#episodeScore').value),review:$('#episodeReview').value}});return}if(e.target.closest('[data-more-episodes]')){try{const page=await invoke('catalogEpisodes',{id:current.id,offset:catalogDetailState.episodes.length});const unique=new Map([...catalogDetailState.episodes,...page.episodes].map(e=>[e.id,e]));catalogDetailState.episodes=[...unique.values()];catalogDetailState.episodeHasMore=catalogDetailState.episodes.length<page.total;catalogClient.details.set(current.id,catalogDetailState);renderCatalogDetail()}catch(err){toast(err.message)}}},true);
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-catalog-open]'))openCatalogWork(e.target.dataset.catalogOpen)});
chrome.addEventListener('dblclick',e=>{if(!e.target.closest('button'))invoke('windowControl','maximize')});
